-- ============================================================================
-- TeknoyCart: Seller Review Notifications (V11)
-- ============================================================================
-- Adds a single in-app notification for the seller when a buyer publishes a
-- review. Reviews are inserted from the Flutter client, so the notification is
-- generated by a database trigger rather than a second client-side write.
--
-- Invariants:
--   1. In-app only. No push/email is queued, so review content never reaches a
--      lock screen or an external inbox without an explicit seller preference.
--   2. Privacy-safe. The notification never includes the buyer's name or id.
--      Anonymous and named reviews both read as "A buyer ...".
--   3. Failure isolation. The trigger catches every exception and returns NEW,
--      so a notification problem can never roll back a review insert.
--   4. Idempotent. One row per review via (user_id, dedupe_key) + ON CONFLICT.
--   5. The reference stays (ORDER, order_id) so the app can open the existing
--      order detail screen, where the seller can read and reply to the review.
-- ============================================================================

-- Extend the notification type constraint without changing any existing value.
ALTER TABLE public.notifications
    DROP CONSTRAINT IF EXISTS chk_notifications_type;

ALTER TABLE public.notifications
    ADD CONSTRAINT chk_notifications_type
    CHECK (type IN ('ORDER_STATUS', 'PAYMENT', 'KYC', 'OFFER', 'REVIEW', 'SYSTEM'));

-- ----------------------------------------------------------------------------
-- Seller review notification trigger function
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_notify_seller_on_review()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_product_name TEXT := 'your item';
BEGIN
    BEGIN
        -- Defensive guards. seller_id is NOT NULL by schema, but a self-review
        -- must never notify the same account.
        IF NEW.seller_id IS NULL OR NEW.seller_id = NEW.buyer_id THEN
            RETURN NEW;
        END IF;

        -- product_reviews.product_id is TEXT while products.product_id is UUID,
        -- so compare as text instead of risking an invalid UUID cast.
        SELECT COALESCE(NULLIF(BTRIM(p.name), ''), 'your item')
          INTO v_product_name
          FROM public.products p
         WHERE p.product_id::TEXT = NEW.product_id
         LIMIT 1;

        INSERT INTO public.notifications (
            user_id,
            title,
            body,
            type,
            reference_id,
            reference_type,
            dedupe_key,
            delivery_channels,
            push_status,
            email_status
        ) VALUES (
            NEW.seller_id,
            '⭐ New Review Received',
            'A buyer rated ' || v_product_name || ' ' || NEW.rating::TEXT ||
                ' out of 5. Tap to view and reply.',
            'REVIEW',
            CASE WHEN NEW.order_id IS NULL THEN NULL ELSE NEW.order_id::TEXT END,
            CASE WHEN NEW.order_id IS NULL THEN NULL ELSE 'ORDER' END,
            'review:' || NEW.review_id::TEXT || ':seller',
            ARRAY['IN_APP'],
            'NOT_APPLICABLE',
            'NOT_APPLICABLE'
        )
        ON CONFLICT (user_id, dedupe_key) DO NOTHING;

    EXCEPTION WHEN OTHERS THEN
        -- Never abort the buyer's review insert because a notification failed.
        RAISE WARNING 'Seller review notification failed for review %: %',
            NEW.review_id, SQLERRM;
    END;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_seller_on_review ON public.product_reviews;

CREATE TRIGGER trg_notify_seller_on_review
    AFTER INSERT ON public.product_reviews
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_notify_seller_on_review();
